// Provider tests run against HTTP cassettes in testdata/cassettes/ and
// never reach the network by default (CI). The cassettes are SYNTHETIC:
// they were generated by TestSynthesizeCassettes from scripted responses
// that follow the documented Messages API shape, not recorded from the
// live API. To regenerate them after a prompt change:
//
//	STRSPC_SYNTHESIZE=1 go test ./src/ruleeval/claude/ -run TestSynthesizeCassettes
//
// Scenarios marked recordable can be re-recorded against the live API with
// STRSPC_RECORD=1 and ANTHROPIC_API_KEY set; the rest only exist in
// synthetic form.

const (
	synthComment = "SYNTHETIC cassette: generated by TestSynthesizeCassettes from scripted responses in provider_test.go, not recorded from the live Anthropic API. Regenerate with STRSPC_SYNTHESIZE=1."
	testModel    = "claude-sonnet-5-5"
)

// scenario describes one cassette-backed test case.
type scenario struct {
	name       string
	recordable bool // can be recorded against the live API (verdict-level checks only)
	single     bool // call Evaluate (per-rule) instead of EvaluateBatch
	cfg        func(*claude.Config)
	inputs     []ruleeval.RuleInput
	diff       string
	script     func(w http.ResponseWriter, body string, call int) // synthetic server behaviour
	check      func(t *testing.T, resp *ruleeval.BatchResponse, err error, p *claude.Provider, rt *replay.Transport)
}

func rule(id, body string, notes ...entity.Note) ruleeval.RuleInput {
	return ruleeval.RuleInput{
		Rule:     entity.Rule{ID: id, Revision: 1, State: "I", Body: body},
		Notes:    notes,
		EntityID: strings.SplitN(id, "-", 2)[0],
		Source:   "./rules/",
		Scope:    "local",
	}
}

const cobraLongRule = "Every cobra command MUST set a Long description."

var diffMissingLong = strings.Join([]string{
	"diff --git a/src/cmd/lint.go b/src/cmd/lint.go",
	"index 1111111..2222222 100644",
	"--- a/src/cmd/lint.go",
	"+++ b/src/cmd/lint.go",
	"@@ -8,6 +8,12 @@ import (",
	" \t\"github.com/spf13/cobra\"",
	" )",
	" ",
	"+func newLintCmd() *cobra.Command {",
	"+\treturn &cobra.Command{",
	"+\t\tUse:   \"lint\",",
	"+\t\tShort: \"Lint entity files\",",
	"+\t}",
	"+}",
	"+",
	" func init() {",
	" \trootCmd.AddCommand(newLintCmd())",
	" }",
}, "\n") + "\n"

var diffWithLong = strings.Join([]string{
	"diff --git a/src/cmd/lint.go b/src/cmd/lint.go",
	"index 1111111..2222222 100644",
	"--- a/src/cmd/lint.go",
	"+++ b/src/cmd/lint.go",
	"@@ -8,6 +8,13 @@ import (",
	" \t\"github.com/spf13/cobra\"",
	" )",
	" ",
	"+func newLintCmd() *cobra.Command {",
	"+\treturn &cobra.Command{",
	"+\t\tUse:   \"lint\",",
	"+\t\tShort: \"Lint entity files\",",
	"+\t\tLong:  \"Validate entity files against the SteerSpec schema and business rules.\",",
	"+\t}",
	"+}",
	"+",
	" func init() {",
	" \trootCmd.AddCommand(newLintCmd())",
	" }",
}, "\n") + "\n"

var diffReadme = strings.Join([]string{
	"diff --git a/README.md b/README.md",
	"index 1111111..2222222 100644",
	"--- a/README.md",
	"+++ b/README.md",
	"@@ -1,3 +1,4 @@",
	" # Project",
	" ",
	" Some words.",
	"+More words about the project.",
}, "\n") + "\n"

// --- synthetic Messages API responses -------------------------------------

type verdictJSON struct {
	RuleID      string         `json:"rule_id"`
	Verdict     string         `json:"verdict"`
	Explanation string         `json:"explanation"`
	Confidence  float64        `json:"confidence"`
	Evidence    []locationJSON `json:"evidence"`
}

type locationJSON struct {
	File    string `json:"file"`
	Line    int    `json:"line"`
	Excerpt string `json:"excerpt"`
}

func verdictsText(vs ...verdictJSON) string {
	for i := range vs {
		if vs[i].Evidence == nil {
			vs[i].Evidence = []locationJSON{}
		}
	}
	b, _ := json.Marshal(map[string]any{"verdicts": vs})
	return string(b)
}

// message renders a Messages API response in the documented shape.
func message(stopReason, text string, extra map[string]any) string {
	content := []any{}
	if text != "" {
		content = append(content, map[string]any{"type": "text", "text": text})
	}
	m := map[string]any{
		"id":            "msg_synthetic_0001",
		"type":          "message",
		"role":          "assistant",
		"model":         testModel,
		"content":       content,
		"stop_reason":   stopReason,
		"stop_sequence": nil,
		"usage": map[string]any{
			"input_tokens":                1200,
			"output_tokens":               96,
			"cache_creation_input_tokens": 900,
			"cache_read_input_tokens":     0,
		},
	}
	for k, v := range extra {
		m[k] = v
	}
	b, _ := json.Marshal(m)
	return string(b)
}

func writeJSON(w http.ResponseWriter, status int, body string) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("request-id", "req_synthetic")
	w.WriteHeader(status)
	_, _ = io.WriteString(w, body)
}

func apiError(status int, typ, msg string) string {
	b, _ := json.Marshal(map[string]any{
		"type":  "error",
		"error": map[string]any{"type": typ, "message": msg},
	})
	return string(b)
}

// --- scenarios ------------------------------------------------------------

func scenarios() []scenario {
	ok := func(w http.ResponseWriter, _ string, _ int) {
		writeJSON(w, 200, message("end_turn", verdictsText(verdictJSON{RuleID: "CMD-001", Verdict: "compliant", Explanation: "Long is set.", Confidence: 0.95}), nil))
	}
	return []scenario{
		{
			name:       "compliant",
			recordable: true,
			inputs:     []ruleeval.RuleInput{rule("CMD-001", cobraLongRule)},
			diff:       diffWithLong,
			script:     ok,
			check: func(t *testing.T, resp *ruleeval.BatchResponse, err error, p *claude.Provider, _ *replay.Transport) {
				if err != nil {
					t.Fatal(err)
				}
				v := resp.Verdicts["CMD-001"]
				if v == nil || v.Verdict != ruleeval.Compliant {
					t.Fatalf("verdict = %+v, want compliant", v)
				}
				u := p.Usage()
				if u.Requests != 1 || u.InputTokens == 0 || u.OutputTokens == 0 {
					t.Errorf("usage not accumulated: %+v", u)
				}
			},
		},
		{
			name:   "single_rule_evaluate",
			single: true,
			inputs: []ruleeval.RuleInput{rule("CMD-001", cobraLongRule)},
			diff:   diffWithLong,
			script: ok,
			check: func(t *testing.T, resp *ruleeval.BatchResponse, err error, _ *claude.Provider, _ *replay.Transport) {
				if err != nil {
					t.Fatal(err)
				}
				if v := resp.Verdicts["CMD-001"]; v == nil || v.Verdict != ruleeval.Compliant {
					t.Fatalf("Evaluate verdict = %+v, want compliant", v)
				}
			},
		},
		{
			name:       "violated_with_evidence",
			recordable: true,
			inputs: []ruleeval.RuleInput{rule("CMD-001", cobraLongRule,
				entity.Note{ID: "CMD-001/01", RuleRef: "CMD-001", Type: "applies_to", Content: "Go files under src/cmd/ constructing cobra.Command values."},
				entity.Note{ID: "CMD-001/02", RuleRef: "CMD-001", Type: "rationale", Content: "Long descriptions feed --help and the docs site."},
			)},
			diff: diffMissingLong,
			script: func(w http.ResponseWriter, _ string, _ int) {
				writeJSON(w, 200, message("end_turn", verdictsText(verdictJSON{
					RuleID: "CMD-001", Verdict: "violated", Confidence: 0.9,
					Explanation: "newLintCmd constructs a cobra.Command with Use and Short but no Long description.",
					Evidence:    []locationJSON{{File: "src/cmd/lint.go", Line: 12, Excerpt: "return &cobra.Command{"}},
				}), nil))
			},
			check: func(t *testing.T, resp *ruleeval.BatchResponse, err error, _ *claude.Provider, _ *replay.Transport) {
				if err != nil {
					t.Fatal(err)
				}
				v := resp.Verdicts["CMD-001"]
				if v == nil || v.Verdict != ruleeval.Violated {
					t.Fatalf("verdict = %+v, want violated", v)
				}
				if len(v.Evidence) == 0 || v.Evidence[0].File != "src/cmd/lint.go" || v.Evidence[0].Line == 0 {
					t.Errorf("expected evidence in src/cmd/lint.go, got %+v", v.Evidence)
				}
				if v.Explanation == "" || v.Confidence <= 0 {
					t.Errorf("expected explanation and confidence, got %+v", v)
				}
			},
		},
		{
			name:       "not_applicable",
			recordable: true,
			inputs:     []ruleeval.RuleInput{rule("CMD-001", cobraLongRule)},
			diff:       diffReadme,
			script: func(w http.ResponseWriter, _ string, _ int) {
				writeJSON(w, 200, message("end_turn", verdictsText(verdictJSON{RuleID: "CMD-001", Verdict: "not_applicable", Explanation: "The diff only touches README.md.", Confidence: 0.98}), nil))
			},
			check: func(t *testing.T, resp *ruleeval.BatchResponse, err error, _ *claude.Provider, _ *replay.Transport) {
				if err != nil {
					t.Fatal(err)
				}
				if v := resp.Verdicts["CMD-001"]; v == nil || v.Verdict != ruleeval.NotApplicable {
					t.Fatalf("verdict = %+v, want not_applicable", v)
				}
			},
		},
		{
			name:   "refusal",
			inputs: []ruleeval.RuleInput{rule("CMD-001", cobraLongRule)},
			diff:   diffMissingLong,
			script: func(w http.ResponseWriter, _ string, _ int) {
				writeJSON(w, 200, message("refusal", "", map[string]any{
					"stop_details": map[string]any{"type": "refusal", "category": "cyber", "explanation": "Synthetic refusal for testing."},
				}))
			},
			check: func(t *testing.T, resp *ruleeval.BatchResponse, err error, p *claude.Provider, _ *replay.Transport) {
				if !errors.Is(err, claude.ErrRefused) || resp != nil {
					t.Fatalf("err = %v (resp %v), want ErrRefused", err, resp)
				}
				if !strings.Contains(err.Error(), "cyber") {
					t.Errorf("refusal error should carry the category, got %q", err)
				}
				if p.Usage().Requests != 1 {
					t.Errorf("a refused request is still billed; usage %+v", p.Usage())
				}
			},
		},
		{
			name:   "max_tokens",
			inputs: []ruleeval.RuleInput{rule("CMD-001", cobraLongRule)},
			diff:   diffMissingLong,
			script: func(w http.ResponseWriter, _ string, _ int) {
				writeJSON(w, 200, message("max_tokens", `{"verdicts":[{"rule_id":"CMD-001","verdict":"viol`, nil))
			},
			check: func(t *testing.T, _ *ruleeval.BatchResponse, err error, _ *claude.Provider, _ *replay.Transport) {
				if !errors.Is(err, claude.ErrTruncated) {
					t.Fatalf("err = %v, want ErrTruncated", err)
				}
			},
		},
		{
			name:   "malformed_json",
			inputs: []ruleeval.RuleInput{rule("CMD-001", cobraLongRule)},
			diff:   diffMissingLong,
			script: func(w http.ResponseWriter, _ string, _ int) {
				writeJSON(w, 200, message("end_turn", "Sure! Here is my evaluation: the rule is violated.", nil))
			},
			check: func(t *testing.T, _ *ruleeval.BatchResponse, err error, _ *claude.Provider, _ *replay.Transport) {
				if !errors.Is(err, claude.ErrMalformed) {
					t.Fatalf("err = %v, want ErrMalformed", err)
				}
			},
		},
		{
			name:   "rate_limited_then_ok",
			inputs: []ruleeval.RuleInput{rule("CMD-001", cobraLongRule)},
			diff:   diffWithLong,
			script: func(w http.ResponseWriter, body string, call int) {
				if call == 1 {
					w.Header().Set("retry-after-ms", "1")
					writeJSON(w, 429, apiError(429, "rate_limit_error", "Synthetic rate limit."))
					return
				}
				ok(w, body, call)
			},
			check: func(t *testing.T, resp *ruleeval.BatchResponse, err error, p *claude.Provider, rt *replay.Transport) {
				if err != nil {
					t.Fatal(err)
				}
				if v := resp.Verdicts["CMD-001"]; v == nil || v.Verdict != ruleeval.Compliant {
					t.Fatalf("verdict = %+v, want compliant after retry", v)
				}
				if rt.Requests() != 2 {
					t.Errorf("transport saw %d requests, want 2 (429 then 200)", rt.Requests())
				}
				if p.Usage().Requests != 1 {
					t.Errorf("usage should count completed responses only, got %+v", p.Usage())
				}
			},
		},
		{
			name:   "two_chunk_diff",
			inputs: []ruleeval.RuleInput{rule("CMD-001", cobraLongRule)},
			// Two files: the first complies, the second violates. A small input
			// budget forces one request per file.
			diff: diffWithLong + strings.ReplaceAll(diffMissingLong, "src/cmd/lint.go", "src/cmd/sync.go"),
			cfg: func(c *claude.Config) {
				// system ≈ 575 tokens + rules ≈ 50 + overhead 256 = 881; the
				// remaining 200 tokens (600 bytes) fit one ~400-byte file per chunk.
				c.MaxInputTokens = 1081
			},
			script: func(w http.ResponseWriter, body string, _ int) {
				if strings.Contains(body, "src/cmd/sync.go") {
					writeJSON(w, 200, message("end_turn", verdictsText(verdictJSON{
						RuleID: "CMD-001", Verdict: "violated", Confidence: 0.9, Explanation: "sync command lacks Long.",
						Evidence: []locationJSON{{File: "src/cmd/sync.go", Line: 12, Excerpt: "return &cobra.Command{"}},
					}), nil))
					return
				}
				ok(w, body, 0)
			},
			check: func(t *testing.T, resp *ruleeval.BatchResponse, err error, p *claude.Provider, rt *replay.Transport) {
				if err != nil {
					t.Fatal(err)
				}
				if rt.Requests() != 2 || p.Usage().Requests != 2 {
					t.Fatalf("expected 2 requests (one per chunk), transport=%d usage=%d", rt.Requests(), p.Usage().Requests)
				}
				v := resp.Verdicts["CMD-001"]
				if v == nil || v.Verdict != ruleeval.Violated {
					t.Fatalf("merged verdict = %+v, want violated (violation wins across chunks)", v)
				}
				if len(v.Evidence) != 1 || v.Evidence[0].File != "src/cmd/sync.go" {
					t.Errorf("merged evidence = %+v", v.Evidence)
				}
				if len(resp.Errors) != 0 {
					t.Errorf("unexpected partial errors: %v", resp.Errors)
				}
			},
		},
		{
			name:   "oversize_hunk",
			inputs: []ruleeval.RuleInput{rule("CMD-001", cobraLongRule)},
			diff:   diffWithLong + bigHunkDiff("src/generated/big.go", 60),
			cfg:    func(c *claude.Config) { c.MaxInputTokens = 1081 },
			script: ok,
			check: func(t *testing.T, resp *ruleeval.BatchResponse, err error, _ *claude.Provider, rt *replay.Transport) {
				if err != nil {
					t.Fatal(err)
				}
				if rt.Requests() != 1 {
					t.Errorf("expected exactly 1 request for the fitting file, got %d", rt.Requests())
				}
				if v := resp.Verdicts["CMD-001"]; v == nil || v.Verdict != ruleeval.Compliant {
					t.Errorf("verdict for the fitting chunk = %+v", v)
				}
				if len(resp.Errors) != 1 || !strings.Contains(resp.Errors[0].Error(), "src/generated/big.go") {
					t.Fatalf("expected one oversize error naming big.go, got %v", resp.Errors)
				}
			},
		},
		{
			name:   "unexpected_rule_id",
			inputs: []ruleeval.RuleInput{rule("CMD-001", cobraLongRule)},
			diff:   diffWithLong,
			script: func(w http.ResponseWriter, _ string, _ int) {
				writeJSON(w, 200, message("end_turn", verdictsText(
					verdictJSON{RuleID: "CMD-001", Verdict: "compliant", Explanation: "ok", Confidence: 0.9},
					verdictJSON{RuleID: "CMD-999", Verdict: "violated", Explanation: "hallucinated", Confidence: 0.5},
				), nil))
			},
			check: func(t *testing.T, resp *ruleeval.BatchResponse, err error, _ *claude.Provider, _ *replay.Transport) {
				if err != nil {
					t.Fatal(err)
				}
				if _, leaked := resp.Verdicts["CMD-999"]; leaked {
					t.Error("unrequested rule id must not be returned")
				}
				if resp.Verdicts["CMD-001"] == nil {
					t.Error("requested verdict must be kept")
				}
				if len(resp.Errors) != 1 || !strings.Contains(resp.Errors[0].Error(), "CMD-999") {
					t.Errorf("expected one error naming CMD-999, got %v", resp.Errors)
				}
			},
		},
		{
			name:   "unauthorized",
			inputs: []ruleeval.RuleInput{rule("CMD-001", cobraLongRule)},
			diff:   diffWithLong,
			script: func(w http.ResponseWriter, _ string, _ int) {
				writeJSON(w, 401, apiError(401, "authentication_error", "invalid x-api-key"))
			},
			check: func(t *testing.T, _ *ruleeval.BatchResponse, err error, _ *claude.Provider, rt *replay.Transport) {
				if !errors.Is(err, ruleeval.ErrUnavailable) {
					t.Fatalf("err = %v, want ErrUnavailable", err)
				}
				if rt.Requests() != 1 {
					t.Errorf("401 must not be retried; transport saw %d requests", rt.Requests())
				}
			},
		},
	}
}

// bigHunkDiff builds a single-hunk file diff with n long added lines.
func bigHunkDiff(path string, n int) string {
	var b strings.Builder
	fmt.Fprintf(&b, "diff --git a/%s b/%s\n--- a/%s\n+++ b/%s\n@@ -0,0 +1,%d @@\n", path, path, path, path, n)
	for i := 0; i < n; i++ {
		fmt.Fprintf(&b, "+var generated%03d = %q\n", i, strings.Repeat("x", 40))
	}
	return b.String()
}

func cassettePath(name string) string {
	return filepath.Join("testdata", "cassettes", name+".json")
}

// runScenario executes sc against the transport rt and runs its checks.
func runScenario(t *testing.T, sc scenario, rt *replay.Transport, cfg claude.Config) {
	t.Helper()
	cfg.HTTPClient = &http.Client{Transport: rt}
	cfg.Model = testModel
	if sc.cfg != nil {
		sc.cfg(&cfg)
	}
	p, err := claude.New(cfg)
	if err != nil {
		t.Fatal(err)
	}
	ctx := context.Background()
	var resp *ruleeval.BatchResponse
	if sc.single {
		in := sc.inputs[0]
		var v *ruleeval.EvalResponse
		v, err = p.Evaluate(ctx, ruleeval.EvalRequest{Rule: in.Rule, Notes: in.Notes, Diff: sc.diff})
		if v != nil {
			resp = &ruleeval.BatchResponse{Verdicts: map[string]*ruleeval.EvalResponse{in.Rule.ID: v}}
		}
	} else {
		resp, err = p.EvaluateBatch(ctx, ruleeval.BatchRequest{EntityID: "CMD", Inputs: sc.inputs, Diff: sc.diff})
	}
	sc.check(t, resp, err, p, rt)
}

// TestProvider_Scenarios replays cassettes (default) or records against the
// live API when STRSPC_RECORD=1 and ANTHROPIC_API_KEY are set.
func TestProvider_Scenarios(t *testing.T) {
	mode := replay.ModeFromEnv()
	key := os.Getenv(claude.EnvAPIKey)
	if mode == replay.ModeRecord && key == "" {
		t.Fatalf("%s=1 requires %s to be set", replay.EnvRecord, claude.EnvAPIKey)
	}
	for _, sc := range scenarios() {
		t.Run(sc.name, func(t *testing.T) {
			var upstream http.RoundTripper
			cfg := claude.Config{APIKey: "test-key"}
			if mode == replay.ModeRecord {
				if !sc.recordable {
					t.Skipf("scenario %q only exists in synthetic form; regenerate with STRSPC_SYNTHESIZE=1", sc.name)
				}
				upstream = http.DefaultTransport
				cfg.APIKey = key
			}
			rt, err := replay.New(cassettePath(sc.name), mode, upstream)
			if err != nil {
				t.Fatal(err) // missing cassette fails CI loudly
			}
			runScenario(t, sc, rt, cfg)
			if mode == replay.ModeRecord {
				if err := rt.Save(); err != nil {
					t.Fatal(err)
				}
			}
		})
	}
}

// TestSynthesizeCassettes regenerates every cassette from the scripted
// responses above by recording the real client against a local server.
// It is a no-op unless STRSPC_SYNTHESIZE=1.
func TestSynthesizeCassettes(t *testing.T) {
	if os.Getenv("STRSPC_SYNTHESIZE") != "1" {
		t.Skip("set STRSPC_SYNTHESIZE=1 to regenerate synthetic cassettes")
	}
	for _, sc := range scenarios() {
		t.Run(sc.name, func(t *testing.T) {
			var calls atomic.Int32
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				body, _ := io.ReadAll(r.Body)
				sc.script(w, string(body), int(calls.Add(1)))
			}))
			defer srv.Close()

			path := cassettePath(sc.name)
			_ = os.Remove(path)
			rt, err := replay.New(path, replay.ModeRecord, http.DefaultTransport)
			if err != nil {
				t.Fatal(err)
			}
			rt.SetComment(synthComment)
			runScenario(t, sc, rt, claude.Config{APIKey: "synthetic-key", BaseURL: srv.URL})
			if err := rt.Save(); err != nil {
				t.Fatal(err)
			}
		})
	}
}

func TestNew_Validation(t *testing.T) {
	t.Setenv(claude.EnvAPIKey, "")
	if _, err := claude.New(claude.Config{}); !errors.Is(err, ruleeval.ErrUnavailable) {
		t.Errorf("missing key: err = %v, want ErrUnavailable", err)
	}
	if _, err := claude.New(claude.Config{APIKey: "k", Effort: "turbo"}); err == nil {
		t.Error("invalid effort must be rejected")
	}
	p, err := claude.New(claude.Config{APIKey: "k"})
	if err != nil {
		t.Fatal(err)
	}
	if p.Model() != claude.DefaultModel || p.PromptVersion() == "" {
		t.Errorf("defaults: model=%q promptVersion=%q", p.Model(), p.PromptVersion())
	}
	t.Setenv(claude.EnvAPIKey, "from-env")
	if _, err := claude.New(claude.Config{}); err != nil {
		t.Errorf("key from env should be accepted: %v", err)
	}
}

func TestEvaluateBatch_Empty(t *testing.T) {
	p, err := claude.New(claude.Config{APIKey: "k", HTTPClient: &http.Client{Transport: failingTransport{}}})
	if err != nil {
		t.Fatal(err)
	}
	resp, err := p.EvaluateBatch(context.Background(), ruleeval.BatchRequest{Diff: "x"})
	if err != nil || len(resp.Verdicts) != 0 {
		t.Fatalf("empty batch should not call the API: %v %v", resp, err)
	}
}

type failingTransport struct{}

func (failingTransport) RoundTrip(*http.Request) (*http.Response, error) {
	return nil, errors.New("unexpected network call")
}
